<?php declare(strict_types=1);namespace App\Models;use App\Core\Crypto;final class User extends Model{protected static string $table='users';public static function findByEmail(string $a):?array{return static::findBy('email',mb_strtolower(trim($a)));}public static function register(string $u,string $m,string $o,string $M='fr',string $s='customer',array $c=[]):int{return static::create(array_merge(['email'=>mb_strtolower(trim($u)),'password_hash'=>Crypto::hashPassword($m),'name'=>$o,'lang'=>$M,'role'=>$s,'country'=>'FR','is_active'=>1],$c));}public static function displayName(array $A):string{return $A['name']?:($A['company']?:$A['email']);}public static function billingSnapshot(array $Y):array{return['name'=>$Y['name'],'company'=>$Y['company'],'vat_number'=>$Y['vat_number'],'address_line1'=>$Y['address_line1'],'address_line2'=>$Y['address_line2'],'postal_code'=>$Y['postal_code'],'city'=>$Y['city'],'country'=>$Y['country'],'email'=>$Y['email']];}public static function isAdminRole(string $n):bool{return in_array($n,\App\Core\Auth::ADMIN_ROLES,true);}}